import{_ as e,o as d,c as o,ag as r}from"./chunks/framework.B3IQijK_.js";const m=JSON.parse('{"title":"Commands and shortcuts","description":"Find Trading Office commands, navigation paths, keyboard shortcuts, and monitor controls.","frontmatter":{"title":"Commands and shortcuts","description":"Find Trading Office commands, navigation paths, keyboard shortcuts, and monitor controls.","outline":2,"head":[["link",{"rel":"canonical","href":"https://tradecli.in/wiki/trading-office/commands"}]]},"headers":[],"relativePath":"trading-office/commands.md","filePath":"trading-office/commands.md"}'),a={name:"trading-office/commands.md"};function n(c,t,i,s,h,l){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="commands-and-shortcuts" tabindex="-1">Commands and shortcuts <a class="header-anchor" href="#commands-and-shortcuts" aria-label="Permalink to &quot;Commands and shortcuts&quot;">​</a></h1><p>Use this page when you know what you want to do and need the exact interface path.</p><div class="info custom-block"><p class="custom-block-title">Current interface names</p><p>The preview interface labels Trading Office as <strong>Hedge Fund</strong>, labels a trading book as a <strong>fund book</strong>, labels the office lead as the <strong>CEO pane</strong>, and retains the <code>/hedgefund:*</code> command namespace.</p></div><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><p>Run these from the <code>tradecli</code> editor.</p><table tabindex="0"><thead><tr><th>Command</th><th>What it opens or does</th></tr></thead><tbody><tr><td><code>/hedgefund:books</code></td><td>Choose or add a trading book, then launch its active team; office lead/CEO pane only</td></tr><tr><td><code>/hedgefund:onboard</code></td><td>Open launch-readiness cards; office lead/CEO pane only</td></tr><tr><td><code>/hedgefund:control</code></td><td>Open the selected book&#39;s Control Center; office lead/CEO pane only</td></tr><tr><td><code>/hedgefund:admin</code></td><td>Configure the selected book, team, mandates, workflows, and LP records</td></tr><tr><td><code>/ideas</code></td><td>Open the Idea Backlog</td></tr><tr><td><code>/backtest</code></td><td>Open the current Backtest Lab menu for the Strategy Lab workflow: new experiment, jobs, approvals, strategies, and help</td></tr><tr><td><code>/strategies</code></td><td>Open the Strategy Library for snapshots, journals, reviews, forward checks, restoration, and paper tickets</td></tr><tr><td><code>/terminal</code></td><td>Open Market Terminal for the active Office paper scope</td></tr><tr><td><code>/trade</code></td><td>Open the entry ticket for the current pending strategy plan</td></tr><tr><td><code>/exit [symbol]</code></td><td>Open Market Terminal with the matching position&#39;s exit ticket; omit the symbol to choose manually</td></tr><tr><td><code>/crons</code></td><td>Open Cron Monitor for scheduled watches</td></tr><tr><td><code>/prefs</code></td><td>Open preferences</td></tr><tr><td><code>/persona</code></td><td>Leave the current persona home and choose another persona</td></tr><tr><td><code>/shortcuts</code></td><td>Toggle the shortcut sheet below the editor</td></tr></tbody></table><p>Scanner opens with <code>Ctrl+Shift+N</code>.</p><h2 id="global-shortcuts" tabindex="-1">Global shortcuts <a class="header-anchor" href="#global-shortcuts" aria-label="Permalink to &quot;Global shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+\\</code></td><td>Abort the current operation, if any, and return home</td></tr><tr><td><code>Esc</code></td><td>Go back or close the current overlay</td></tr><tr><td><code>Ctrl+Shift+S</code></td><td>Open preferences</td></tr><tr><td><code>Ctrl+Shift+M</code></td><td>Open Market Terminal</td></tr><tr><td><code>Ctrl+Shift+N</code></td><td>Open Scanner</td></tr><tr><td><code>?</code></td><td>Toggle the shortcut sheet when the editor is empty</td></tr></tbody></table><h2 id="market-terminal" tabindex="-1">Market Terminal <a class="header-anchor" href="#market-terminal" aria-label="Permalink to &quot;Market Terminal&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>1</code>–<code>5</code></td><td>Change instrument filter; the broker filter appears where supported</td></tr><tr><td><code>↑</code> / <code>↓</code></td><td>Select a position</td></tr><tr><td><code>T</code></td><td>Open an entry ticket from the pending strategy plan</td></tr><tr><td><code>X</code></td><td>Open an exit ticket for the selected Office position</td></tr><tr><td><code>R</code></td><td>Refresh live marks</td></tr><tr><td><code>Esc</code></td><td>Close the terminal</td></tr></tbody></table><p>The exit ticket starts with the full open quantity at the current mark. Adjust the quantity when you want a partial exit.</p><h2 id="cron-monitor" tabindex="-1">Cron Monitor <a class="header-anchor" href="#cron-monitor" aria-label="Permalink to &quot;Cron Monitor&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>Select a scheduled watch</td></tr><tr><td><code>R</code></td><td>Refresh status</td></tr><tr><td><code>K</code> or <code>X</code></td><td>Request permanent removal of the selected watch</td></tr><tr><td><code>Y</code> / <code>N</code></td><td>Confirm or cancel removal</td></tr><tr><td><code>Esc</code> or <code>Q</code></td><td>Close the monitor</td></tr></tbody></table><p>Removing a watch deletes the job. Use <strong>Stop watch</strong> in conversation when you want to retain it in a paused state.</p><h2 id="find-the-right-surface" tabindex="-1">Find the right surface <a class="header-anchor" href="#find-the-right-surface" aria-label="Permalink to &quot;Find the right surface&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Surface</th></tr></thead><tbody><tr><td>Capture or reopen a hypothesis</td><td>Idea Backlog</td></tr><tr><td>Create, inspect, or approve an experiment</td><td>Backtest Lab</td></tr><tr><td>Inspect a promoted version or review its journal</td><td>Strategy Library</td></tr><tr><td>Scan for candidates</td><td>Scanner</td></tr><tr><td>Enter, inspect, or exit a paper position</td><td>Market Terminal</td></tr><tr><td>Manage employees, mandates, and workflows</td><td>Control Center</td></tr><tr><td>Inspect scheduled watches</td><td>Cron Monitor</td></tr></tbody></table><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/trading-sandbox-website-preview/wiki/trading-office/concepts">Concepts and terminology</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/setup">Set up your office</a></li><li><a href="/trading-sandbox-website-preview/wiki/getting-started/tradingview-setup">Connect TradingView</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/watches">Automation tools</a></li></ul>',19)])])}const f=e(a,[["render",n]]);export{m as __pageData,f as default};
